using System.Collections.Generic;using UnityEngine;using UnityEngine.Rendering;using LighthouseKeepers.Core;
namespace LighthouseKeepers.WatchDemo {
 [DefaultExecutionOrder(1600)]public sealed class PracticalAtmosphere:MonoBehaviour {
  WatchDemoController watch;Transform head;Material brass,glow,haze;readonly List<Material> handMaterials=new();readonly HashSet<int> litHands=new();readonly List<(Light light,Renderer bulb)> fixtures=new();readonly List<Renderer> rays=new();MaterialPropertyBlock block;float scan;bool oldFog;FogMode oldMode;float oldDensity;Color oldColour;
  public static void Create(WatchDemoController w){if(!VisualPassSettings.Current||!VisualPassSettings.Current.lighting)return;var p=w.gameObject.AddComponent<PracticalAtmosphere>();p.watch=w;}
  void Start(){head=Camera.main.transform;oldFog=RenderSettings.fog;oldMode=RenderSettings.fogMode;oldDensity=RenderSettings.fogDensity;oldColour=RenderSettings.fogColor;block=new MaterialPropertyBlock();brass=Resources.Load<Material>("VisualMaterials/Brass");glow=new Material(Shader.Find("Universal Render Pipeline/Lit"));glow.EnableKeyword("_EMISSION");glow.SetColor("_BaseColor",new Color(.65f,.43f,.13f));haze=new Material(Resources.Load<Shader>("PracticalHaze"));haze.SetColor("_BaseColor",new Color(.45f,.56f,.67f,.035f));
   // Window shafts are fixed physical cards, not camera-facing overlays. Six cheap draws.
   for(int floor=0;floor<4;floor++)foreach(float side in new[]{-1f,1f}){var p=Primitive("Cold window shaft",PrimitiveType.Quad,new Vector3(side*2.65f,floor*3.3f+1.4f,.8f),new Vector3(1.2f,3,.01f),haze);p.transform.rotation=Quaternion.Euler(25,side*60,0);rays.Add(p.GetComponent<Renderer>());}
   Scan();
  }
  GameObject Primitive(string name,PrimitiveType type,Vector3 pos,Vector3 size,Material mat){var go=GameObject.CreatePrimitive(type);go.name=name;go.transform.SetParent(transform,true);go.transform.position=pos;go.transform.localScale=size;var c=go.GetComponent<Collider>();if(c){c.enabled=false;Destroy(c);}var r=go.GetComponent<Renderer>();r.sharedMaterial=mat;r.shadowCastingMode=ShadowCastingMode.Off;return go;}
  void Scan(){scan=Time.time+5;
   // Local skin previously opted out of probes while relying on realtime fixtures.
   // Keep its accepted material/pose; illuminate it with the newly baked floor probes.
   foreach(var hand in FindObjectsByType<LighthouseKeepers.Gameplay.Interaction.HandRig>(FindObjectsSortMode.None))foreach(var skin in hand.GetComponentsInChildren<SkinnedMeshRenderer>()){if(!litHands.Add(skin.GetInstanceID()))continue;skin.lightProbeUsage=LightProbeUsage.BlendProbes;var source=skin.sharedMaterial;if(!source||!source.HasProperty("_BaseColor"))continue;var material=new Material(source){name=source.name+" / baked-room visibility"};material.EnableKeyword("_EMISSION");material.SetColor("_EmissionColor",source.GetColor("_BaseColor")*.08f);skin.sharedMaterial=material;handMaterials.Add(material);}
foreach(var l in FindObjectsByType<Light>(FindObjectsInactive.Include,FindObjectsSortMode.None)){if(l.transform.parent&&l.transform.parent.Find("Frosted service lamp"))continue;if(l.type!=LightType.Point||l.name.Contains("lantern")||l.name.Contains("gallery"))continue;bool known=false;foreach(var f in fixtures)if(f.light==l){known=true;break;}if(known)continue;
    // Existing authored lamp housings remain; generated guide/service lights gain a real housing.
    if(!(l.name.Contains("guide")||l.name.Contains("service")||l.name.Contains("Shielded")||l.name.Contains("practical")))continue;
    var mounted=l.transform.position;float nearest=4;Vector3 normal=Vector3.zero,wallPoint=mounted;for(int d=0;d<8;d++){var dir=Quaternion.Euler(0,d*45,0)*Vector3.forward;foreach(var hit in Physics.RaycastAll(mounted,dir,4,~0,QueryTriggerInteraction.Ignore))if(hit.collider.name.Contains("Wall")&&hit.distance<nearest){nearest=hit.distance;normal=hit.normal;wallPoint=hit.point;}}if(nearest>=4)continue;mounted=wallPoint+normal*.07f;
    // Existing wall-mounted stair fixtures cover this route. Avoid a second housing behind a rail.
    bool blocked=false;var fittingBounds=new Bounds(mounted,new Vector3(.20f,.24f,.20f));foreach(var rail in FindObjectsByType<Renderer>(FindObjectsSortMode.None))if(rail.enabled&&rail.name.StartsWith("SM_Rail_")&&rail.bounds.Intersects(fittingBounds)){blocked=true;break;}
    if(blocked){fixtures.Add((l,null));continue;}
    var back=Primitive("Wall fixed lamp bracket",PrimitiveType.Cube,mounted-normal*.035f,new Vector3(.14f,.18f,.03f),brass);back.transform.rotation=Quaternion.LookRotation(normal);var bulb=Primitive("Caged practical bulb",PrimitiveType.Sphere,mounted,new Vector3(.055f,.09f,.055f),glow).GetComponent<Renderer>();Primitive("Brass lamp cap",PrimitiveType.Cylinder,mounted+Vector3.up*.065f,new Vector3(.10f,.012f,.10f),brass);for(int n=0;n<4;n++){float a=n*Mathf.PI*.5f;Primitive("Lamp cage rib",PrimitiveType.Cube,mounted+new Vector3(Mathf.Cos(a)*.043f,0,Mathf.Sin(a)*.043f),new Vector3(.008f,.12f,.008f),brass);}fixtures.Add((l,bulb));
   }}
  void LateUpdate(){if(!head)return;if(Time.time>=scan)Scan();var state=watch.State;bool inside=(head.position.z< -5&&Mathf.Abs(head.position.x)<3.5f&&head.position.z> -11.5f)||new Vector2(head.position.x,head.position.z).magnitude<3.8f;float interior=head.position.y<3.3f?.018f:.009f;if(state.Tension!=null&&!state.HasPower(PowerCircuit.Lights))interior=Mathf.Lerp(interior,state.Sprint5.blackoutFogDensity,state.Tension.Value);float dawn=state.Tutorial?0:Mathf.SmoothStep(0,1,(float)(state.Elapsed/state.Duration-.85)/.15f);float stage=(state.Storm.Stage-1)/3f;RenderSettings.fog=true;RenderSettings.fogMode=FogMode.ExponentialSquared;RenderSettings.fogDensity=Mathf.Lerp(RenderSettings.fogDensity,inside?interior:Mathf.Lerp(.018f,.032f,stage),Time.deltaTime);RenderSettings.fogColor=Color.Lerp(RenderSettings.fogColor,Color.Lerp(inside?new Color(.09f,.075f,.06f):new Color(.065f,.095f,.13f),new Color(.22f,.22f,.18f),dawn),Time.deltaTime);
   foreach(var f in fixtures)if(f.light&&f.bulb){float intensity=Mathf.Clamp(f.light.intensity,.03f,2);block.Clear();block.SetColor("_EmissionColor",f.light.color*intensity);block.SetColor("_BaseColor",f.light.color*.6f);f.bulb.SetPropertyBlock(block);}haze.SetColor("_BaseColor",Color.Lerp(new Color(.45f,.56f,.67f,.025f),new Color(.65f,.60f,.43f,.035f),dawn));
  }
  void OnDestroy(){if(KeeperAudioMix.Instance)KeeperAudioMix.Instance.PreScareQuiet=false;RenderSettings.fog=oldFog;RenderSettings.fogMode=oldMode;RenderSettings.fogDensity=oldDensity;RenderSettings.fogColor=oldColour;foreach(var m in handMaterials)if(m)Destroy(m);if(glow)Destroy(glow);if(haze)Destroy(haze);}
 }
}
